window.QUIZ = (window.QUIZ || []).concat([
  { id: "7-001", ch: 7, sec: "7.1", page: 131, type: "recall", level: 1,
    q: "The book groups salt problems in irrigated soils into three types. Which set is correct?",
    opts: ["Salinity, sodicity, and toxicity", "Salinity, acidity, and alkalinity", "Sodicity, compaction, and toxicity", "Salinity, nitrate leaching, and toxicity"], a: 0,
    why: "The amount and type of salts decide the problem: salinity (total dissolved salt), sodicity (excess sodium that ruins structure), and toxicity (specific ions such as Na, Cl, and B). Acidity and compaction are not salt problems in this chapter.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-002", ch: 7, sec: "7.1", page: 132, type: "recall", level: 1,
    q: "What is the primary cause of increasing salt content in irrigated soils?",
    opts: ["Fertilizer applications that add potassium and nitrate salts", "Evapotranspiration, which removes water and leaves the salts behind", "Rainfall that carries dust and sea spray onto fields", "Weathering of the soil clay during each growing season"], a: 1,
    why: "As roots extract water and the surface evaporates, the salts stay in the soil and concentrate. Fertilizer and dust add some salt, but the book names evapotranspiration as the primary cause.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-003", ch: 7, sec: "7.1", page: 132, type: "recall", level: 2,
    q: "In some salt-affected soils, nodules or layers of precipitated salt are found within the profile. What are these called?",
    opts: ["Gypsic crust", "Fragipan", "Plinthite", "Caliche"], a: 3,
    why: "The book calls nodules or layers of precipitated salts within the soil caliche. A fragipan and plinthite are soil horizons formed by other processes, not salt precipitation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-004", ch: 7, sec: "7.1", page: 132, type: "recall", level: 1,
    q: "A soil affected by excess sodium is called a sodic soil. What is the outmoded term for it?",
    opts: ["Saline soil", "Calcareous soil", "Alkaline soil", "Acid sulfate soil"], a: 2,
    why: "The book notes sodic soil was once called alkaline soil. A saline soil has excess total salt, which is a different problem from excess sodium.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-005", ch: 7, sec: "7.1", page: 133, type: "concept", level: 2,
    q: "Why does high soil water salinity reduce crop growth even when the soil is at field capacity?",
    opts: ["Salt crystals physically block the root hairs and stop all water uptake", "Salts raise the matric potential so water drains out of the root zone faster", "The osmotic potential of the soil water drops, so roots must spend more energy to extract water", "Salt reduces the soil water content held at field capacity by about half"], a: 2,
    why: "Salinity lowers (makes more negative) the osmotic potential outside the root, shrinking the potential difference that drives uptake. The plant spends energy on extraction instead of growth, so it is smaller and yields less. Water is present but less available.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-006", ch: 7, sec: "7.1", page: 131, type: "concept", level: 1,
    q: "Why are soils and waters in humid regions normally low in salt?",
    opts: ["Humid region soils contain no salt-bearing minerals", "Rainfall exceeds crop water use, so excess water percolates and flushes salts below the root zone", "High humidity prevents salts from dissolving in soil water", "Crops in humid regions take up most of the salt in their tissue"], a: 1,
    why: "Where rain exceeds ET, water moves down through the profile and carries salts with it. In dry climates ET exceeds rain, little water percolates, and salts build up. All soils contain some salt, so the mineral argument is wrong.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-007", ch: 7, sec: "7.1", page: 133, type: "recall", level: 2,
    q: "Which three specific ions does the book single out as having considerable potential to damage plants through toxicity?",
    opts: ["Calcium, magnesium, and sulfate", "Nitrate, phosphate, and potassium", "Bicarbonate, carbonate, and calcium", "Sodium, chloride, and boron"], a: 3,
    why: "Figure 7.6 shows leaf burn from sodium (Na+), chloride (Cl−), and boron (B). Woody crops such as trees are especially sensitive. Calcium and magnesium actually improve soil structure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-008", ch: 7, sec: "7.2", page: 133, type: "concept", level: 2,
    q: "Why are saline soils often found in lowlands and depressions?",
    opts: ["Salt moves with water, and water drains to and collects in low areas, often with poor internal drainage and a high water table", "Low areas receive less irrigation water so salts are not diluted", "Salts are heavier than soil particles and roll downhill with erosion", "Depressions have finer soils that produce salts by weathering faster"], a: 0,
    why: "Salts travel with water, so they accumulate where water collects and evaporates. Low spots often have restricted internal drainage and a shallow water table, which brings salt up by capillarity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-009", ch: 7, sec: "7.2", page: 134, type: "recall", level: 2,
    q: "Which geologic formation does the book cite as a notorious source of salt in the upper Colorado River Basin?",
    opts: ["Ogallala formation", "Dakota sandstone", "Mancos shale", "Niobrara chalk"], a: 2,
    why: "Saline marine shales deposited under ancient seas are major salt sources. The book names the Mancos shale in Colorado, Wyoming, and Utah. The Ogallala is an aquifer formation, not a cited salt source.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-010", ch: 7, sec: "7.2", page: 134, type: "recall", level: 1,
    q: "Once irrigated land is in production, what is the primary source of new salt added to the root zone?",
    opts: ["Rainfall", "Crop residue decomposition", "Weathering of primary minerals in the root zone", "The irrigation water"], a: 3,
    why: "The book states that once lands are in production the primary source of salt is the irrigation water, and that salt is additive to whatever salt is already in the soil.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-011", ch: 7, sec: "7.2", page: 134, type: "calc", level: 1,
    q: "Irrigation water contains 800 mg/L of dissolved salt. How much salt is applied per acre with 24 inches of irrigation?",
    opts: ["4,340 lb/ac", "19,200 lb/ac", "434 lb/ac", "2,170 lb/ac"], a: 0,
    why: "C1 = 0.226 × C × da = 0.226 × 800 ppm × 24 in = 4,339 lb/ac, rounded to 4,340 lb/ac. 19,200 multiplies 800 by 24 without the 0.226 factor, and 2,170 is the tons value mistaken for pounds after dividing by 2.",
    eq: null, calc: "salt-applied", fig: null, table: null },
  { id: "7-012", ch: 7, sec: "7.2", page: 134, type: "calc", level: 2,
    q: "A well supplies water at 600 mg/L. A grower applies 18 inches on a 120-acre field. How many tons of salt are added to the field this season?",
    opts: ["1.2 tons", "146 tons", "2,441 tons", "293 tons"], a: 1,
    why: "Salt per acre = 0.226 × 600 × 18 = 2,441 lb/ac. Total = 2,441 × 120 / 2,000 = 146 tons. 2,441 is the lb/ac value, 1.2 tons is the per-acre amount, and 293 tons divides by 1,000 instead of 2,000 lb per ton.",
    eq: null, calc: "salt-applied", fig: null, table: null },
  { id: "7-013", ch: 7, sec: "7.2", page: 134, type: "calc", level: 3,
    q: "Irrigation water has an EC of 1.0 dS/m. Estimate the salt applied per acre by 30 inches of this water.",
    opts: ["About 6,780 lb/ac (3.4 tons/ac)", "About 2,170 lb/ac (1.1 tons/ac)", "About 4,340 lb/ac (2.2 tons/ac)", "About 680 lb/ac (0.34 tons/ac)"], a: 2,
    why: "First convert EC to concentration with Eq. 7.2: C = 640 × 1.0 = 640 mg/L. Then C1 = 0.226 × 640 × 30 = 4,339 lb/ac, about 2.2 tons/ac. Using 1,000 mg/L per dS/m gives 6,780, which is the wrong conversion factor.",
    eq: "7.2", calc: "salt-applied", fig: null, table: null },
  { id: "7-014", ch: 7, sec: "7.3", page: 134, type: "recall", level: 1,
    q: "The common unit for EC in natural systems is dS/m. It is numerically equal to which outmoded unit?",
    opts: ["µmho/cm", "mmho/cm", "S/cm", "mg/L"], a: 1,
    why: "1 dS/m = 0.1 S/m and is numerically equal to millimhos per centimeter. µmho/cm is 1,000 times smaller, and mg/L is a concentration, not a conductivity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-015", ch: 7, sec: "7.3", page: 135, type: "recall", level: 1,
    q: "What does ECe measure?",
    opts: ["The EC of solution extracted from a soil sample brought to saturation in the lab", "The EC of the irrigation water at the well head", "The EC of the drainage water leaving the root zone", "The EC of soil water at field capacity measured in place"], a: 0,
    why: "ECe is the electrical conductivity of the saturated extract: the soil sample is saturated with distilled water and solution is drawn off by vacuum filtration. Field-water-content methods exist but are not ECe.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-016", ch: 7, sec: "7.3", page: 134, type: "recall", level: 2,
    q: "Between 15 and 35 °C, how does EC change with solution temperature?",
    opts: ["It falls about 2% per 1 °C increase", "It rises about 10% per 1 °C increase", "It does not change in that range", "It rises about 2% per 1 °C increase"], a: 3,
    why: "Warmer solutions conduct better. The book gives about 2% per degree, which is why EC is reported at 25 °C.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-017", ch: 7, sec: "7.3", page: 134, type: "calc", level: 1,
    q: "A soil extract has an EC of 4.0 dS/m. What is the approximate osmotic potential of the solution?",
    opts: ["11.1 bars (magnitude)", "0.09 bars (magnitude)", "1.44 bars (magnitude)", "2,560 bars (magnitude)"], a: 2,
    why: "Eq. 7.1: Ψo = 0.36 × EC = 0.36 × 4.0 = 1.44 bars (the potential itself is negative). 11.1 divides by 0.36 instead of multiplying, and 2,560 mixes in the 640 factor from Eq. 7.2.",
    eq: "7.1", calc: "eq-7.1", fig: null, table: null },
  { id: "7-018", ch: 7, sec: "7.3", page: 134, type: "calc", level: 1,
    q: "Irrigation water has an EC of 1.5 dS/m. Approximately what is its total salt concentration?",
    opts: ["427 mg/L", "960 mg/L", "0.54 mg/L", "1,500 mg/L"], a: 1,
    why: "Eq. 7.2: C = 640 × EC = 640 × 1.5 = 960 mg/L. 427 divides 640 by 1.5, and 1,500 assumes 1,000 mg/L per dS/m.",
    eq: "7.2", calc: "eq-7.2", fig: null, table: null },
  { id: "7-019", ch: 7, sec: "7.3", page: 134, type: "calc", level: 2,
    q: "A saturated extract measures 3.0 dS/m at 30 °C. What EC should be reported at 25 °C?",
    opts: ["2.7 dS/m", "3.3 dS/m", "3.0 dS/m", "2.4 dS/m"], a: 0,
    why: "EC rises about 2% per °C, so correct downward: EC25 = 3.0 × [1 − 0.02 × (30 − 25)] = 3.0 × 0.90 = 2.7 dS/m. 3.3 corrects in the wrong direction.",
    eq: null, calc: "ec-temp", fig: null, table: null },
  { id: "7-020", ch: 7, sec: "7.3", page: 134, type: "calc", level: 2,
    q: "A saturated extract measures 5.0 dS/m at 20 °C. What EC should be reported and used in calculations?",
    opts: ["4.5 dS/m", "5.0 dS/m", "6.0 dS/m", "5.5 dS/m"], a: 3,
    why: "The sample is 5 °C colder than 25 °C, so it reads low. EC25 = 5.0 × [1 − 0.02 × (20 − 25)] = 5.0 × 1.10 = 5.5 dS/m. 4.5 subtracts the correction instead of adding it.",
    eq: null, calc: "ec-temp", fig: null, table: null },
  { id: "7-021", ch: 7, sec: "7.3", page: 134, type: "concept", level: 1,
    q: "Why can electrical conductivity be used to estimate the salt concentration of a solution?",
    opts: ["Salt crystals are metallic and conduct electricity like wire", "Pure water conducts well and salts reduce its conductivity in proportion", "EC measures the weight of dry salt left after evaporation", "Salts dissociate into charged ions that carry electric current, and conductivity rises as concentration rises"], a: 3,
    why: "Dissolved salts split into cations and anions. More ions means more current at a given voltage, so EC tracks salt concentration. Pure water is a poor conductor.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-022", ch: 7, sec: "7.4", page: 135, type: "recall", level: 1,
    q: "In the salt tolerance model, what is the threshold T?",
    opts: ["The salinity at which yield falls to 50%", "The salinity of irrigation water at which crop damage begins", "The maximum root zone salinity (ECe) that does not reduce yield appreciably below nonsaline yield", "The salinity at which the crop dies completely"], a: 2,
    why: "T is where the zero-slope plateau and the declining line intersect: the highest ECe with no appreciable yield loss. It is expressed in ECe units (saturated soil extract), not irrigation water EC.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-023", ch: 7, sec: "7.4", page: 135, type: "concept", level: 2,
    q: "Crop response to salinity is sigmoidal, yet the book represents it with two straight lines. What do the two lines represent?",
    opts: ["A tolerance plateau with zero slope, then a line whose slope is the yield loss per unit increase in salinity", "One line for germination and one for mature plant tolerance", "One line for sprinkler irrigation and one for surface irrigation", "A rising line for nutrient benefit and a falling line for toxicity"], a: 0,
    why: "The plateau ends at the threshold T. Beyond it, yield drops at slope S (% per dS/m). This two-line fit is what Eq. 7.3 describes and is practical for management.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-024", ch: 7, sec: "7.4", page: 135, type: "calc", level: 1,
    q: "Corn (T = 1.7 dS/m, S = 12%/(dS/m)) is grown where the mean root zone ECe is 3.5 dS/m. What relative yield is expected?",
    opts: ["58%", "78%", "22%", "88%"], a: 1,
    why: "Eq. 7.3: Yr = 100 − 12 × (3.5 − 1.7) = 100 − 21.6 = 78.4%, about 78%. 58% uses ECe without subtracting T, and 22% is the yield loss, not the relative yield.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: null },
  { id: "7-025", ch: 7, sec: "7.4", page: 137, type: "calc", level: 2,
    q: "A saline area of a corn field has a soil solution concentration of 2,200 mg/L. Nonsaline parts yield 200 bu/ac. Estimate the yield in the saline area. Use T = 1.7 dS/m and S = 12%/(dS/m).",
    opts: ["180 bu/ac", "42 bu/ac", "158 bu/ac", "118 bu/ac"], a: 2,
    why: "ECe = 2,200 / 640 = 3.44 dS/m. Yr = 100 − 12 × (3.44 − 1.7) = 79.1%. Ya = 0.791 × 200 = 158 bu/ac. 42 bu/ac is the loss, not the yield, and 118 skips subtracting the threshold.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: null },
  { id: "7-026", ch: 7, sec: "7.4", page: 137, type: "calc", level: 2,
    q: "Alfalfa (T = 2.0 dS/m, S = 7.3%/(dS/m)) yields 8 tons/ac on nonsaline ground. What yield is expected where ECe averages 5.0 dS/m?",
    opts: ["5.1 tons/ac", "1.8 tons/ac", "7.4 tons/ac", "6.2 tons/ac"], a: 3,
    why: "Yr = 100 − 7.3 × (5.0 − 2.0) = 78.1%. Yield = 0.781 × 8 = 6.2 tons/ac. 5.1 skips the threshold (100 − 7.3 × 5), and 1.8 is the tons lost.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: null },
  { id: "7-027", ch: 7, sec: "7.4", page: 137, type: "calc", level: 3,
    q: "A grain sorghum field has a soil solution concentration of 2,500 mg/L. Using T = 6.8 dS/m and S = 16%/(dS/m), what yield reduction is expected?",
    opts: ["About 46% reduction", "None, because ECe (about 3.9 dS/m) is below the threshold", "About 37% reduction", "About 63% reduction"], a: 1,
    why: "ECe = 2,500 / 640 = 3.9 dS/m, which is below T = 6.8, so Eq. 7.3 does not apply and yield is not reduced. 63% is 16 × 3.9 with no threshold, 37% is the matching relative yield, and 46% uses (T − ECe) with the sign flipped.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: null },
  { id: "7-028", ch: 7, sec: "7.4", page: 137, type: "calc", level: 3,
    q: "What is the highest root zone ECe at which wheat (T = 6.0 dS/m, S = 7.1%/(dS/m)) still yields 90% of nonsaline yield?",
    opts: ["7.4 dS/m", "6.7 dS/m", "12.7 dS/m", "1.4 dS/m"], a: 0,
    why: "Solve Eq. 7.3 for ECe: ECe = T + (100 − Yr)/S = 6.0 + 10/7.1 = 7.4 dS/m. 1.4 is only the increment above T, and 12.7 divides 90 (the relative yield) by the slope instead of the 10% loss.",
    eq: "7.3", calc: "tab-7.2", fig: null, table: null },
  { id: "7-029", ch: 7, sec: "7.4", page: 137, type: "calc", level: 3,
    q: "Tomato has T = 2.5 dS/m and S = 9.9%/(dS/m). At what ECe would Eq. 7.3 predict zero yield?",
    opts: ["10.1 dS/m", "7.6 dS/m", "24.8 dS/m", "12.6 dS/m"], a: 3,
    why: "Set Yr = 0: ECe = T + 100/S = 2.5 + 100/9.9 = 2.5 + 10.1 = 12.6 dS/m. 10.1 forgets to add the threshold.",
    eq: "7.3", calc: "tab-7.2", fig: null, table: null },
  { id: "7-030", ch: 7, sec: "7.4", page: 135, type: "figure", level: 1,
    q: "Using Figure 7.7, at about what soil salinity (ECe) does relative corn grain yield begin to decline?",
    opts: ["About 0.6 dS/m", "About 1.7 dS/m", "About 3.0 dS/m", "About 4.6 dS/m"], a: 1,
    why: "The plateau at 100% ends where the lines intersect near 1.7 dS/m, which matches the corn threshold in Table 7.2. 4.6 dS/m is the right end of the data where yield is about 25%.",
    eq: null, calc: null, fig: "7.7", table: null },
  { id: "7-031", ch: 7, sec: "7.4", page: 137, type: "figure", level: 2,
    q: "Using Figure 7.9, a crop still gives about 50% relative yield at an ECe of 12 dS/m. Which qualitative class is it in?",
    opts: ["Moderately sensitive", "Sensitive", "Moderately tolerant", "Tolerant"], a: 2,
    why: "At 50% yield the division lines cross near 4.9, 9.6, 15, and 21 dS/m. The point 12 dS/m lies between the second and third lines, which is the moderately tolerant zone.",
    eq: null, calc: null, fig: "7.9", table: null },
  { id: "7-032", ch: 7, sec: "7.4", page: 136, type: "table", level: 1,
    q: "Per Table 7.2, which of these grain crops is the most salt tolerant?",
    opts: ["Barley", "Corn", "Rice", "Cowpea"], a: 0,
    why: "Barley has T = 8.0 dS/m and S = 5.0%/(dS/m), rated tolerant. Corn (1.7), rice (3.0), and cowpea (4.9) have lower thresholds and steeper 12%/(dS/m) slopes.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-033", ch: 7, sec: "7.4", page: 136, type: "table", level: 1,
    q: "Per Table 7.2, what is the salt tolerance threshold of alfalfa?",
    opts: ["7.3 dS/m", "1.5 dS/m", "6.9 dS/m", "2.0 dS/m"], a: 3,
    why: "Alfalfa: T = 2.0 dS/m, S = 7.3%/(dS/m), moderately sensitive. 7.3 is its slope, and 6.9 is Bermuda grass.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-034", ch: 7, sec: "7.4", page: 136, type: "table", level: 2,
    q: "Per Table 7.2, which crop loses yield fastest once its threshold is exceeded?",
    opts: ["Plum", "Strawberry", "Peanut", "Apricot"], a: 1,
    why: "Slopes: strawberry 33, plum 31, peanut 29, apricot 24 %/(dS/m). Strawberry has the steepest decline.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-035", ch: 7, sec: "7.4", page: 136, type: "table", level: 2,
    q: "Rice has a threshold of 3.0 dS/m, higher than corn's 1.7 dS/m. What qualitative rating does Table 7.2 give rice?",
    opts: ["Moderately sensitive", "Moderately tolerant", "Sensitive", "Tolerant"], a: 2,
    why: "Rice is rated s (sensitive) even though its threshold exceeds corn's (ms). The rating reflects where the whole response line falls in Figure 7.9, not the threshold alone.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-036", ch: 7, sec: "7.4", page: 136, type: "table", level: 2,
    q: "Which grain crop in Table 7.2 is rated moderately tolerant with a slope of only 7.1%/(dS/m)?",
    opts: ["Wheat", "Sorghum", "Soybean", "Barley"], a: 0,
    why: "Wheat: T = 6.0 dS/m, S = 7.1, mt. Sorghum (16) and soybean (20) are also mt but with steeper slopes, and barley is rated t.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-037", ch: 7, sec: "7.4", page: 136, type: "table", level: 3,
    q: "Soybean has the Table 7.2 values for threshold and slope. What relative yield is expected at a root zone ECe of 7.0 dS/m?",
    opts: ["80%", "40%", "60%", "86%"], a: 2,
    why: "Table 7.2 gives soybean T = 5.0 dS/m and S = 20%/(dS/m). Yr = 100 − 20 × (7.0 − 5.0) = 60%. 40% is the loss, and 86% uses the wheat slope.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: "7.2" },
  { id: "7-038", ch: 7, sec: "7.4", page: 136, type: "table", level: 1,
    q: "Per Table 7.3, irrigation water with an EC of 1.5 dS/m is classed as what, and how often do crop problems occur?",
    opts: ["Slightly saline, rare problems", "Saline, common problems", "Fresh, no problems", "Moderately saline, occasional problems"], a: 3,
    why: "Table 7.3: moderately saline water is 1 to 2 dS/m (600 to 1,200 mg/L) with occasional crop problems.",
    eq: null, calc: "tab-7.3", fig: null, table: "7.3" },
  { id: "7-039", ch: 7, sec: "7.4", page: 136, type: "table", level: 1,
    q: "A water sample contains 2,000 mg/L of dissolved salts. Per Table 7.3, how is it classed?",
    opts: ["Moderately saline, crop problems occasional", "Saline, crop problems common", "Highly saline, crop problems severe", "Slightly saline, crop problems rare"], a: 1,
    why: "Saline water spans 1,200 to 2,400 mg/L (2 to 4 dS/m) with common problems. 2,000 mg/L falls in that band.",
    eq: null, calc: "tab-7.3", fig: null, table: "7.3" },
  { id: "7-040", ch: 7, sec: "7.10", page: 143, type: "recall", level: 2,
    q: "According to the chapter summary, by about what factor do crops differ in their sensitivity to salinity?",
    opts: ["Nearly 10", "About 2", "About 100", "About 1.5"], a: 0,
    why: "The summary says crops differ by nearly a factor of 10. Table 7.2 thresholds run from 1.0 dS/m (bean, carrot, strawberry) to 15 dS/m (guayule).",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-041", ch: 7, sec: "7.4", page: 136, type: "table", level: 3,
    q: "Per Table 7.2, which crop has the highest salt tolerance threshold listed?",
    opts: ["Barley", "Guayule", "Cotton", "Date palm"], a: 1,
    why: "Guayule has T = 15 dS/m. Barley is 8.0, cotton 7.7, and date palm 4.0 dS/m.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-042", ch: 7, sec: "7.5", page: 137, type: "concept", level: 1,
    q: "What happens to soil structure when sodium is the predominant adsorbed cation?",
    opts: ["Clay particles flocculate into a granular, permeable structure", "Soil pores enlarge and infiltration increases sharply", "Organic matter binds into stable aggregates", "Clay particles swell and aggregates disperse, reducing water entry and movement"], a: 3,
    why: "Excess sodium swells clays and disperses aggregates, so infiltration and hydraulic conductivity fall. Calcium and magnesium dominance gives the granular, permeable structure instead.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-043", ch: 7, sec: "7.5", page: 138, type: "recall", level: 2,
    q: "In Eq. 7.4 for SAR, in what units must the sodium, calcium, and magnesium concentrations be entered?",
    opts: ["Moles of charge per cubic meter (mol_c/m³)", "Milligrams per liter (mg/L)", "Parts per million by weight", "dS/m"], a: 0,
    why: "The book defines SAR with concentrations in mol_c/m³. Lab reports in meq/L are converted with Eq. 7.5 (divide by the ion valence) before computing SAR.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-044", ch: 7, sec: "7.5", page: 138, type: "calc", level: 2,
    q: "Water analysis shows sodium 20 meq/L, calcium 6 meq/L, and magnesium 2 meq/L. Using the book's Eq. 7.4 and 7.5, what is the SAR?",
    opts: ["7.1 (mol_c/m³)^1/2", "5.0 (mol_c/m³)^1/2", "10 (mol_c/m³)^1/2", "2.5 (mol_c/m³)^1/2"], a: 2,
    why: "Convert: Na = 20/1 = 20, Ca = 6/2 = 3, Mg = 2/2 = 1 mol_c/m³. SAR = 20/√(3 + 1) = 20/2 = 10. 7.1 uses meq/L directly (20/√8), and 5.0 forgets the square root.",
    eq: "7.4", calc: "eq-7.4-7.5", fig: null, table: null },
  { id: "7-045", ch: 7, sec: "7.5", page: 138, type: "calc", level: 2,
    q: "An irrigation water has Na = 12 meq/L, Ca = 10 meq/L, and Mg = 8 meq/L. What is its SAR by the book's method?",
    opts: ["2.8 (mol_c/m³)^1/2", "1.3 (mol_c/m³)^1/2", "4.0 (mol_c/m³)^1/2", "0.67 (mol_c/m³)^1/2"], a: 2,
    why: "Ca = 10/2 = 5, Mg = 8/2 = 4 mol_c/m³, Na = 12. SAR = 12/√9 = 4.0. 2.8 skips the valence conversion (12/√18), and 1.3 drops the square root (12/9).",
    eq: "7.4", calc: "eq-7.4-7.5", fig: null, table: null },
  { id: "7-046", ch: 7, sec: "7.5", page: 138, type: "calc", level: 1,
    q: "A lab reports calcium at 30 meq/L. Using Eq. 7.5, what is the calcium concentration in mol_c/m³?",
    opts: ["30 mol_c/m³", "60 mol_c/m³", "7.5 mol_c/m³", "15 mol_c/m³"], a: 3,
    why: "Eq. 7.5: mol_c/m³ = (meq/L)/valence. Calcium valence is +2, so 30/2 = 15. 60 multiplies by the valence instead of dividing.",
    eq: "7.5", calc: "eq-7.4-7.5", fig: null, table: null },
  { id: "7-047", ch: 7, sec: "7.5", page: 138, type: "calc", level: 3,
    q: "Water has Na = 33 meq/L and EC = 0.4 dS/m. If calcium plus magnesium in mol_c/m³ were raised from 16 to 36 by adding gypsum, what would the SAR become?",
    opts: ["5.5 (mol_c/m³)^1/2", "8.3 (mol_c/m³)^1/2", "0.92 (mol_c/m³)^1/2", "4.1 (mol_c/m³)^1/2"], a: 0,
    why: "SAR = 33/√36 = 33/6 = 5.5, down from 33/√16 = 8.25. More calcium lowers SAR. 0.92 drops the square root (33/36), and 4.1 would require Ca + Mg of 64 mol_c/m³.",
    eq: "7.4", calc: "eq-7.4-7.5", fig: null, table: null },
  { id: "7-048", ch: 7, sec: "7.5", page: 138, type: "figure", level: 2,
    q: "Using Figure 7.10, what infiltration effect is expected for water with SAR = 20 and ECa = 1.0 dS/m?",
    opts: ["Slight to moderate reduction", "Severe reduction in rate of infiltration", "No reduction", "Increase in rate of infiltration"], a: 1,
    why: "At ECa = 1.0 dS/m, the left (severe) boundary is near SAR 13.6 and the right boundary near SAR 3.4. SAR 20 lies above and left of the severe line.",
    eq: null, calc: null, fig: "7.10", table: null },
  { id: "7-049", ch: 7, sec: "7.5", page: 138, type: "figure", level: 2,
    q: "Using Figure 7.10, what infiltration effect is expected for water with SAR = 10 and ECa = 3.0 dS/m?",
    opts: ["Slight to moderate reduction", "Severe reduction", "No reduction in rate of infiltration", "Cannot be determined because SAR is above 8"], a: 2,
    why: "At ECa = 3.0 dS/m the right boundary is near SAR 17. SAR 10 lies to the right of and below that line, in the no reduction zone. Higher salinity keeps clays flocculated.",
    eq: null, calc: null, fig: "7.10", table: null },
  { id: "7-050", ch: 7, sec: "7.5", page: 138, type: "figure", level: 3,
    q: "Using Figure 7.10, what infiltration effect is expected for water with SAR = 15 and ECa = 2.0 dS/m?",
    opts: ["Severe reduction", "Slight to moderate reduction", "No reduction", "Severe at first, then none after one season"], a: 1,
    why: "At ECa = 2.0 dS/m the right line is near SAR 10 and the severe line near SAR 22. SAR 15 falls between the two lines.",
    eq: null, calc: null, fig: "7.10", table: null },
  { id: "7-051", ch: 7, sec: "7.5", page: 138, type: "concept", level: 3,
    q: "Figure 7.10 shows that at the same SAR, a water with lower EC is more likely to cause an infiltration problem. Why?",
    opts: ["Low EC water carries more sodium per liter", "High EC water dissolves soil lime and adds calcium", "Low EC water has a higher osmotic potential that pulls water out of the soil", "Low salt water lets clays disperse, while higher salinity keeps clays flocculated even with the same sodium ratio"], a: 3,
    why: "Electrolyte concentration holds clay particles together. Very pure water with moderate sodium disperses clay readily, which is why the hazard boundaries slope upward with EC.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-052", ch: 7, sec: "7.5", page: 138, type: "concept", level: 3,
    q: "When is Eq. 7.4 valid for estimating the SAR of the soil water from the SAR of the irrigation water?",
    opts: ["Under steady-state conditions where the irrigation water SAR approximates the soil water SAR", "Only when the soil is at the wilting point", "Only for waters with EC above 4 dS/m", "Whenever the water contains no magnesium"], a: 0,
    why: "The book states Eq. 7.4 applies to soil water at steady state. Under nonsteady conditions the SAR of the soil water needs adjustment.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-053", ch: 7, sec: "7.6", page: 138, type: "concept", level: 2,
    q: "Why can sprinkler irrigation with water high in chloride cause damage that drip irrigation with the same water does not?",
    opts: ["Chloride can be absorbed directly through wetted leaves", "Sprinklers add chloride from the aluminum pipe", "Drip water has its chloride removed by the emitter filters", "Sprinklers raise soil chloride faster than drip"], a: 0,
    why: "Some ions, like chloride, enter leaves directly when foliage is wetted. Drip keeps leaves dry, so only root uptake matters.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-054", ch: 7, sec: "7.6", page: 138, type: "recall", level: 2,
    q: "Under which weather conditions is foliar damage from sprinkling saline water most acute?",
    opts: ["Low temperature and high humidity", "High temperature and low humidity", "Cloudy, calm, and cool days", "Night irrigation with dew"], a: 1,
    why: "Hot dry conditions evaporate water from the leaf fast, concentrating salt on the leaf surface. The book singles out high temperature and low humidity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-055", ch: 7, sec: "7.6", page: 138, type: "concept", level: 1,
    q: "How does toxicity differ from the general salinity effect?",
    opts: ["Toxicity is caused by total dissolved salts, while salinity is caused by sodium only", "Toxicity affects only soil structure", "There is no difference, the terms are interchangeable", "Toxicity comes from uptake and accumulation of specific ions in plant tissue, while salinity acts through total salt and osmotic stress"], a: 3,
    why: "Salinity is about total dissolved salt lowering osmotic potential. Toxicity is about particular ions such as boron, chloride, and sodium building up in tissue, and it depends heavily on the crop.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-056", ch: 7, sec: "7.7", page: 139, type: "recall", level: 1,
    q: "How does the book define leaching?",
    opts: ["Removal of salt crusts by scraping the soil surface", "Any irrigation applied after harvest", "The net downward movement of soil water and solutes", "Upward movement of salts by capillary rise"], a: 2,
    why: "Leaching is the net downward movement of soil water and solutes, the key to irrigating where salts are a hazard.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-057", ch: 7, sec: "7.7", page: 139, type: "recall", level: 1,
    q: "What is the leaching requirement, Lr?",
    opts: ["The actual fraction of infiltrated water that drains below the root zone", "The total depth of water needed to reclaim a saline soil", "The ratio of rain to irrigation water", "The minimum leaching fraction that will prevent a reduction in crop yield"], a: 3,
    why: "Lr is the required (minimum) fraction. The actual fraction is Lf = dp/dt from Eq. 7.6a.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-058", ch: 7, sec: "7.7", page: 139, type: "calc", level: 1,
    q: "During a season 24 inches of irrigation and 6 inches of rain infiltrate, and 4 inches drain below the root zone. What is the actual leaching fraction?",
    opts: ["0.17", "0.13", "0.67", "0.20"], a: 1,
    why: "Eq. 7.6b: dt = dz + dr = 24 + 6 = 30 in. Eq. 7.6a: Lf = dp/dt = 4/30 = 0.133, about 0.13. 0.17 divides by the irrigation depth only (4/24).",
    eq: "7.6b", calc: "eq-7.6", fig: null, table: null },
  { id: "7-059", ch: 7, sec: "7.7", page: 139, type: "calc", level: 1,
    q: "Irrigation water at 1.2 dS/m infiltrates 20 inches and salt-free rain infiltrates 5 inches. What is the weighted salinity of the applied water?",
    opts: ["0.96 dS/m", "1.20 dS/m", "1.50 dS/m", "0.60 dS/m"], a: 0,
    why: "Eq. 7.7: Ca = (1.2 × 20 + 0 × 5)/(20 + 5) = 24/25 = 0.96 dS/m. 1.20 ignores the rain dilution, and 1.50 divides by 16 instead of 25.",
    eq: "7.7", calc: "eq-7.7", fig: null, table: null },
  { id: "7-060", ch: 7, sec: "7.7", page: 139, type: "calc", level: 3,
    q: "Irrigation water is 0.8 dS/m. During the year 400 mm of irrigation and 200 mm of rain infiltrate. Water draining below the root zone is 3.2 dS/m. What is the leaching fraction?",
    opts: ["0.25", "0.33", "0.17", "0.13"], a: 2,
    why: "Ca = (0.8 × 400)/(400 + 200) = 0.533 dS/m. Lf = Ca/Cd = 0.533/3.2 = 0.17. 0.25 uses the irrigation water salinity (0.8/3.2) without rain dilution.",
    eq: "7.6a", calc: "leaching-fraction", fig: null, table: null },
  { id: "7-061", ch: 7, sec: "7.7", page: 139, type: "calc", level: 2,
    q: "The applied water averages 1.5 dS/m, and the drainage water may not exceed 6 dS/m without yield loss. If 30 inches infiltrate, what depth must drain below the root zone?",
    opts: ["4.0 in", "1.5 in", "7.5 in", "120 in"], a: 2,
    why: "Eq. 7.8: Lr = ECa/ECd* = 1.5/6 = 0.25. dp* = Lr × dt = 0.25 × 30 = 7.5 in. 120 in inverts the ratio (6/1.5 × 30).",
    eq: "7.8", calc: "eq-7.8", fig: null, table: null },
  { id: "7-062", ch: 7, sec: "7.7", page: 139, type: "calc", level: 3,
    q: "Irrigation water is 2.0 dS/m and no rain infiltrates. A sample of drainage water reads 10 dS/m, and 32 inches of irrigation infiltrated. How much water drained below the root zone?",
    opts: ["6.4 in", "25.6 in", "3.2 in", "160 in"], a: 0,
    why: "Lf = Ca/Cd = 2/10 = 0.20 (Eq. 7.6a). dp = Lf × dt = 0.20 × 32 = 6.4 in. 25.6 in is the water held back in the root zone (0.80 × 32), and 160 in inverts the ratio (Cd/Ca × 32).",
    eq: "7.6a", calc: "leaching-fraction", fig: null, table: null },
  { id: "7-063", ch: 7, sec: "7.7", page: 139, type: "concept", level: 3,
    q: "A field's actual leaching fraction Lf is less than the crop's leaching requirement Lr. What field condition does this indicate?",
    opts: ["More water is draining than needed and the excess carries nitrate and salt to groundwater", "Salts are accumulating in the root zone and yields will decline once salinity passes the threshold", "The field is at steady state with no yield risk", "The irrigation water must be fresh"], a: 1,
    why: "Lf below Lr means not enough water passes through to hold root zone salinity at the target. Lf above Lr means extra drainage, wasted water, and more saline drainage to dispose of.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-064", ch: 7, sec: "7.7", page: 140, type: "figure", level: 2,
    q: "Using Figure 7.11, what leaching requirement applies when ECa = 4 dS/m and the crop threshold T = 1.7 dS/m (corn)?",
    opts: ["About 0.15", "About 0.05", "About 0.10", "About 0.30"], a: 3,
    why: "The point (ECa 4, T 1.7) falls on the Lr = 0.30 line, which passes through about T = 1.7 at ECa = 4 dS/m. Corn is sensitive, so salty water forces heavy leaching.",
    eq: null, calc: "fig-7.11", fig: "7.11", table: null },
  { id: "7-065", ch: 7, sec: "7.7", page: 140, type: "figure", level: 2,
    q: "Using Figure 7.11, a crop with T = 6.0 dS/m (wheat) is irrigated with ECa = 3 dS/m. What is the leaching requirement?",
    opts: ["About 0.20", "About 0.10", "About 0.30", "About 0.05"], a: 1,
    why: "The 0.10 line passes through about T = 5.8 at ECa = 3 dS/m, so the point (3, 6.0) sits just on the low side of 0.10. Wheat's high threshold keeps Lr small.",
    eq: null, calc: "fig-7.11", fig: "7.11", table: null },
  { id: "7-066", ch: 7, sec: "7.7", page: 140, type: "figure", level: 3,
    q: "Using Figure 7.11, alfalfa (T = 2.0 dS/m) is irrigated with water whose ECa is 1.5 dS/m. Estimate the leaching requirement.",
    opts: ["About 0.30", "About 0.07", "About 0.22", "About 0.14"], a: 3,
    why: "The ratio T/ECa = 1.33 places the point just above the 0.15 line (which passes T = 1.85 at ECa = 1.5) and well below the 0.10 line, so Lr is about 0.14.",
    eq: null, calc: "fig-7.11", fig: "7.11", table: null },
  { id: "7-067", ch: 7, sec: "7.7", page: 140, type: "figure", level: 1,
    q: "In Figure 7.11, for a fixed salinity of applied water, how does the leaching requirement change as the crop's salt tolerance threshold increases?",
    opts: ["It increases", "It stays the same", "It decreases", "It first increases, then decreases"], a: 2,
    why: "Moving up the T axis at a fixed ECa crosses lines of smaller Lr (0.30, 0.20, 0.15, 0.10, 0.05). A more tolerant crop needs less leaching.",
    eq: null, calc: null, fig: "7.11", table: null },
  { id: "7-068", ch: 7, sec: "7.7", page: 140, type: "calc", level: 3,
    q: "Tomatoes (T = 2.5 dS/m) are irrigated with 16 inches of 3 dS/m water. Rainfall contributes 10 inches instead of 4 inches. What is the weighted ECa and the leaching requirement from Figure 7.11?",
    opts: ["ECa = 1.85 dS/m, Lr about 0.14", "ECa = 2.40 dS/m, Lr about 0.17", "ECa = 3.00 dS/m, Lr about 0.22", "ECa = 1.85 dS/m, Lr about 0.30"], a: 0,
    why: "Eq. 7.7: ECa = 3 × 16/(16 + 10) = 1.85 dS/m. With T = 2.5, T/ECa = 1.35, which sits just above the 0.15 line, giving Lr about 0.14. 2.40 and 0.17 are the original Example 7.5 values with 4 inches of rain.",
    eq: "7.7", calc: "fig-7.11", fig: "7.11", table: null },
  { id: "7-069", ch: 7, sec: "7.7", page: 140, type: "concept", level: 2,
    q: "Many annual crops become more salt tolerant as the season progresses. How can a manager use this?",
    opts: ["Leach heavily at the end of the season when the crop is most sensitive", "Apply the saltiest water at planting when the crop is most tolerant", "Start the season with low salinity, then let soil salinity rise gradually and leach with rain or pre-plant irrigation before the next crop", "Skip leaching entirely because tolerance always outpaces salt buildup"], a: 2,
    why: "If salinity is low at planting and adequate low salt water is applied, salinity can climb through the season. Winter rain or dormant season irrigation can then leach before the next crop.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-070", ch: 7, sec: "7.7", page: 140, type: "concept", level: 2,
    q: "When does the book say leaching is actually required?",
    opts: ["At every irrigation regardless of salinity", "Only when the irrigation water exceeds 4 dS/m", "Only after the soil becomes sodic", "Only once accumulated soil salinity surpasses the crop's salt tolerance threshold"], a: 3,
    why: "Leaching can be done each irrigation or seasonally or less often, as long as root zone salinity stays below the threshold. Before that, it is not needed.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-071", ch: 7, sec: "7.7", page: 140, type: "concept", level: 2,
    q: "Part of a field is overirrigated and drains salt freely, while drier parts show salt and water stress. What does the book recommend?",
    opts: ["Apply more water to the whole field until the dry areas recover", "Improve the uniformity of the irrigation system rather than applying more water", "Stop irrigating the wet areas completely", "Add gypsum to the dry areas"], a: 1,
    why: "Nonuniform application leaves some areas short. The book says this is best solved with a more uniform system, not by adding water everywhere to cover the low spots.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-072", ch: 7, sec: "7.7", page: 141, type: "concept", level: 3,
    q: "How do transient (non-steady-state) models compare with the steady-state leaching requirement in Figure 7.11?",
    opts: ["Transient models predict that the steady-state approach overestimates the leaching requirement", "Transient models predict a leaching requirement about twice as high", "Both give identical results because salts move at steady state in the field", "Transient models show leaching is never required"], a: 0,
    why: "Steady state never occurs in the field. Transient models (Letey et al., 2011, Corwin and Grattan, 2018) show the steady-state model overestimates Lr and the saline drainage sent to the environment, though these models need large data sets.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-073", ch: 7, sec: "7.7", page: 139, type: "recall", level: 1,
    q: "In Eq. 7.7, what salt concentration does the book assign to rainfall?",
    opts: ["The same as irrigation water", "0.5 dS/m", "Zero", "Half the irrigation water salinity"], a: 2,
    why: "Rain is so low in salt that Cr is taken as zero, so the Cr dr term drops out.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-074", ch: 7, sec: "7.8", page: 141, type: "recall", level: 1,
    q: "What is the only proven method of reclaiming salt-affected soils?",
    opts: ["Leaching accumulated salts below the crop root zone", "Removing the top 6 inches of soil", "Growing salt-accumulating plants and removing them", "Adding organic matter to bind the salts"], a: 0,
    why: "The book states leaching below the root zone is the only proven method. Sodic soils may need an amendment or deep tillage first.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-075", ch: 7, sec: "7.8", page: 141, type: "recall", level: 2,
    q: "In Eq. 7.9 for continuous ponding, which K values does the book give?",
    opts: ["Peat 0.1, clay loam 0.3, sandy loam 0.45", "Peat 0.3, clay loam 0.45, sandy loam 0.1", "All soils 0.1", "Peat 0.45, clay loam 0.3, sandy loam 0.1"], a: 3,
    why: "K is larger for soils that hold more solution in small pores: organic (peat) 0.45, fine-textured (clay loam) 0.3, coarse (sandy loam) 0.1. The 0.1 for all soils applies to intermittent ponding or sprinkling (Eq. 7.10).",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-076", ch: 7, sec: "7.8", page: 142, type: "calc", level: 1,
    q: "A clay loam (K = 0.3) is to be reclaimed by continuous ponding to a depth of 4 ft, from ECe 12 dS/m to 3 dS/m. How much water must leach through?",
    opts: ["1.6 ft", "4.8 ft", "0.3 ft", "16 ft"], a: 1,
    why: "Eq. 7.9: dL = K × ds × (Co/Cf) = 0.3 × 4 × (12/3) = 4.8 ft. 1.6 ft uses K = 0.1, and 0.3 ft inverts the salinity ratio.",
    eq: "7.9", calc: "eq-7.9-7.10", fig: null, table: null },
  { id: "7-077", ch: 7, sec: "7.8", page: 142, type: "calc", level: 2,
    q: "A peat soil (K = 0.45) is reclaimed by continuous ponding to 2 ft deep, from ECe 8 dS/m to 2 dS/m. How much leaching water is needed?",
    opts: ["2.4 ft", "0.8 ft", "3.6 ft", "0.23 ft"], a: 2,
    why: "dL = 0.45 × 2 × (8/2) = 3.6 ft. 2.4 ft uses the clay loam K of 0.3, and 0.23 ft inverts the salinity ratio.",
    eq: "7.9", calc: "eq-7.9-7.10", fig: null, table: null },
  { id: "7-078", ch: 7, sec: "7.8", page: 142, type: "calc", level: 2,
    q: "A saline field is to be reclaimed to 3 ft by sprinkling without ponding, from ECe 15 dS/m to 3 dS/m. How much water must be applied for leaching?",
    opts: ["4.5 ft (54 in)", "1.5 ft (18 in)", "0.06 ft (0.7 in)", "6.75 ft (81 in)"], a: 1,
    why: "Eq. 7.10: dL = 0.1 × ds × (Co/Cf) = 0.1 × 3 × 5 = 1.5 ft. 4.5 ft uses the clay loam ponding K of 0.3, and 6.75 uses the peat K.",
    eq: "7.10", calc: "eq-7.9-7.10", fig: null, table: null },
  { id: "7-079", ch: 7, sec: "7.8", page: 142, type: "calc", level: 3,
    q: "A clay loam is to be reclaimed to 3 ft from ECe 10 dS/m to 2 dS/m. How much water does sprinkling save compared with continuous ponding?",
    opts: ["1.5 ft (3.0 ft ponding vs 1.5 ft sprinkling)", "None, both need 4.5 ft", "6.0 ft (7.5 ft ponding vs 1.5 ft sprinkling)", "3.0 ft (4.5 ft ponding vs 1.5 ft sprinkling)"], a: 3,
    why: "Ponding: 0.3 × 3 × 10/2 = 4.5 ft. Sprinkling: 0.1 × 3 × 5 = 1.5 ft. Savings = 3.0 ft, two-thirds less water, though it takes longer.",
    eq: "7.9", calc: "eq-7.9-7.10", fig: null, table: null },
  { id: "7-080", ch: 7, sec: "7.8", page: 141, type: "figure", level: 2,
    q: "Using Figure 7.12, after leaching a clay loam by continuous ponding with water equal to the soil depth (dL/ds = 1.0), what fraction of the initial salt remains?",
    opts: ["About 0.3", "About 0.1", "About 0.45", "About 0.6"], a: 0,
    why: "The clay loam curve passes about 0.3 at dL/ds = 1.0, matching Eq. 7.9 with K = 0.3. About 70% of the salt has been removed. 0.45 is the peat curve.",
    eq: null, calc: "eq-7.9-7.10", fig: "7.12", table: null },
  { id: "7-081", ch: 7, sec: "7.8", page: 141, type: "figure", level: 2,
    q: "Using Figure 7.12, what fraction of initial salt remains in a sandy loam after continuously ponded leaching with dL/ds = 0.5?",
    opts: ["About 0.2", "About 0.05", "About 0.6", "About 0.9"], a: 0,
    why: "The sandy loam curve reads about 0.2 at dL/ds = 0.5 (K/0.5 = 0.1/0.5 = 0.2). Coarse soils leach most efficiently under ponding.",
    eq: null, calc: null, fig: "7.12", table: null },
  { id: "7-082", ch: 7, sec: "7.8", page: 141, type: "concept", level: 2,
    q: "What does the initial offset at the top of each curve in Figure 7.12 represent?",
    opts: ["Salt dissolved from the subsoil at the start of ponding", "Evaporation losses during the first day of ponding", "The effect of the amendment on sodium", "Water that must be added to the profile before leaching begins"], a: 3,
    why: "Before salts move out, the profile must first be wetted up. The book says the offset indicates water that must be added before leaching commences.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-083", ch: 7, sec: "7.8", page: 142, type: "concept", level: 3,
    q: "Why does intermittent ponding or sprinkling leach salt with less water than continuous ponding, especially in fine-textured soils?",
    opts: ["Sprinkler water has lower salinity than ponded water", "Ponded water evaporates and leaves salt behind", "In a drier soil, more of the flow passes through fine pores and displaces the saline solution more efficiently", "Sprinkling compacts the surface and slows drainage"], a: 2,
    why: "When saturated, much saline solution sits in small pores while water bypasses through large ones. At lower water content the flow goes through fine pores, so dispersion and diffusion displace salt better.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-084", ch: 7, sec: "7.8", page: 142, type: "concept", level: 1,
    q: "What is the main disadvantage of reclaiming by intermittent ponding or sprinkling compared with continuous ponding?",
    opts: ["It needs about three times more water", "It may take longer to finish", "It works only in sandy soils", "It cannot reduce ECe below 4 dS/m"], a: 1,
    why: "Intermittent methods save water but the reclamation period can be extended beyond that of continuous ponding.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-085", ch: 7, sec: "7.8", page: 143, type: "recall", level: 2,
    q: "Which amendments supply calcium directly to replace sodium in a sodic soil?",
    opts: ["Sulfur, sulfuric acid, and pyrite", "Potassium chloride and urea", "Gypsum, lime, and calcium chloride", "Sodium nitrate and borax"], a: 2,
    why: "Gypsum, lime, and calcium chloride contain calcium. Sulfur, sulfuric acid, and pyrite contain none but react to dissolve calcium already in the soil.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-086", ch: 7, sec: "7.8", page: 143, type: "concept", level: 3,
    q: "A sodic soil is calcareous (contains free lime). Why might sulfur be a useful amendment even though it contains no calcium?",
    opts: ["Sulfur oxidizes to acid that dissolves the soil's lime, releasing calcium to replace sodium", "Sulfur binds sodium into an insoluble crystal", "Sulfur raises soil pH, which flocculates the clay", "Sulfur adds sodium-free salinity that dilutes the soil"], a: 0,
    why: "The book lists sulfur, sulfuric acid, and pyrite as amendments that react to dissolve calcium already present. On calcareous soils this frees calcium for exchange.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-087", ch: 7, sec: "7.8", page: 143, type: "concept", level: 3,
    q: "A grower has lime sulfur (9% Ca and 24% S). Would it help reclaim a sodic soil, and why?",
    opts: ["No, any sulfur product raises sodium hazard", "No, calcium is not involved in sodic soil reclamation", "Yes, but only because it raises soil EC", "Yes, it supplies calcium directly and its sulfur can dissolve additional calcium already in the soil"], a: 3,
    why: "It works both ways described in Section 7.8.2: the calcium exchanges for sodium, and the sulfur reacts to dissolve soil calcium.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-088", ch: 7, sec: "7.8", page: 143, type: "concept", level: 2,
    q: "How does the successive dilution method reclaim a sodic soil?",
    opts: ["Apply low salinity water first, then increase salinity in steps", "Apply high salinity water containing calcium first, then dilute it in steps with low salinity water until only low salinity water is applied", "Alternate ponding and drying without any saline water", "Mix gypsum into the irrigation water at a constant rate"], a: 1,
    why: "High electrolyte water keeps the soil permeable while calcium replaces sodium. Stepping down salinity avoids the dispersion that pure water would cause on a sodic soil.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-089", ch: 7, sec: "7.8", page: 143, type: "concept", level: 2,
    q: "When can deep tillage reduce or eliminate the need for an amendment on a sodic soil?",
    opts: ["When the soil is a deep uniform sand", "When the sodic layer extends below 6 ft", "When calcium is present in the subsoil and can be mixed into a shallow sodic layer", "When the irrigation water has a high SAR"], a: 2,
    why: "Deep plowing brings subsoil calcium (such as gypsum or lime layers) up into the shallow sodic layer, supplying the calcium that an amendment would.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-090", ch: 7, sec: "7.9", page: 143, type: "recall", level: 2,
    q: "Lohman et al. (1988) estimated salinity damages in the lower Colorado River basin. What was the annual total and the share to agriculture?",
    opts: ["$311 million per year total, $113 million to agriculture", "$113 million per year total, $31 million to agriculture", "$500 million per year total, $311 million to agriculture", "$42 million per year total, $11 million to agriculture"], a: 0,
    why: "Damages for 1976 to 1985 were $311 million per year using a 500 mg/L reference (the drinking water standard), of which $113 million was agricultural.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-091", ch: 7, sec: "7.9", page: 143, type: "recall", level: 2,
    q: "Experience in California indicates what share of land area must be devoted to evaporation ponds for saline drainage?",
    opts: ["1 to 2%", "10 to 14%", "25 to 30%", "40 to 50%"], a: 1,
    why: "The book cites 10 to 14% of the land area, which along with construction cost and leakage concerns makes ponds unattractive.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-092", ch: 7, sec: "7.4", page: 137, type: "scenario", level: 2,
    q: "\"My soil test came back with a root zone ECe of 3.0 dS/m on my corn ground. How much yield is that costing me?\" What do you tell the grower?",
    opts: ["No loss, corn tolerates up to 4 dS/m", "About 36% loss, relative yield about 64%", "About 3% loss, almost nothing", "About 16% loss, relative yield about 84% (T = 1.7, S = 12)"], a: 3,
    why: "Yr = 100 − 12 × (3.0 − 1.7) = 84.4%, so about 16% loss. 64% is Example 7.2's answer at 4.7 dS/m, not this soil.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: null },
  { id: "7-093", ch: 7, sec: "7.4", page: 136, type: "scenario", level: 3,
    q: "\"My well tests 2.4 dS/m. I want to plant dry beans next year. Any problem?\" What is the best answer?",
    opts: ["Yes, the water alone is above the bean threshold of 1.0 dS/m, so leaching needs are very high and a more tolerant crop is safer", "No, 2.4 dS/m is classed as fresh water", "No, beans are rated tolerant", "Only if the field is sprinkled at night"], a: 0,
    why: "Bean has T = 1.0 dS/m and S = 19%/(dS/m), rated sensitive. ECa of 2.4 exceeds T itself, so Figure 7.11 falls off the chart (Lr above 0.30). Table 7.3 calls 2.4 dS/m saline with common problems.",
    eq: null, calc: null, fig: "7.11", table: "7.2" },
  { id: "7-094", ch: 7, sec: "7.1", page: 132, type: "scenario", level: 1,
    q: "\"I'm seeing a white crust along the tops of my furrow beds by midsummer.\" What is happening, and what do you check first?",
    opts: ["Fertilizer is burning on the surface, so cut the nitrogen rate", "It is lime from the irrigation pipe, so flush the pipeline", "It is a fungal mat, so apply a fungicide", "Salt is precipitating as water evaporates from the bed tops, so sample ECe in the bed root zone"], a: 3,
    why: "Water moves up into the beds and evaporates, leaving salt as a white to gray crust (Figure 7.2). Measure ECe where seed and roots sit to judge the threat.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-095", ch: 7, sec: "7.2", page: 133, type: "scenario", level: 2,
    q: "\"My cotton stand is poor only in the low spots of the field.\" What should you check first?",
    opts: ["Seed quality in the planter boxes", "Soil salinity and drainage in the low spots, since salts collect where water drains and accumulates", "The pH of the irrigation water", "Nitrogen rate in the high spots"], a: 1,
    why: "Low areas collect water and salt, often with a high water table. Excess salinity there prevents germination or kills seedlings (Figure 7.3).",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-096", ch: 7, sec: "7.3", page: 134, type: "scenario", level: 2,
    q: "\"My lab sheet shows EC 6.0 dS/m measured at 30 °C. Is that the number I use with the crop tables?\" What do you tell the grower?",
    opts: ["Yes, temperature does not affect EC", "No, correct it to about 6.6 dS/m", "No, correct it to 25 °C first, which gives about 5.4 dS/m", "No, divide it by 640 first"], a: 2,
    why: "Crop tolerance values are based on EC at 25 °C. EC25 = 6.0 × [1 − 0.02 × (30 − 25)] = 5.4 dS/m. 6.6 corrects in the wrong direction.",
    eq: null, calc: "ec-temp", fig: null, table: null },
  { id: "7-097", ch: 7, sec: "7.5", page: 138, type: "scenario", level: 3,
    q: "\"Our canal water is very clean, EC about 0.2 dS/m, but water ponds and the surface crusts badly. The SAR is about 6.\" What is the likely cause and remedy?",
    opts: ["Too much salt in the water, so leach harder", "A sodicity effect from very low salinity water, so add a calcium amendment such as gypsum and break the crust", "Boron toxicity, so switch to drip", "Compaction only, the water quality is ideal"], a: 1,
    why: "On Figure 7.10, SAR 6 at ECa 0.2 dS/m lies left of the severe boundary. Very pure water disperses clays. Adding calcium (gypsum) raises electrolyte and lowers the sodium effect.",
    eq: null, calc: null, fig: "7.10", table: null },
  { id: "7-098", ch: 7, sec: "7.8", page: 142, type: "scenario", level: 3,
    q: "\"I need to reclaim a salty clay loam field, but my water is limited this year. Should I flood it or sprinkle it?\" What do you advise?",
    opts: ["Sprinkle or pond intermittently, which takes about one-third the water of continuous ponding but more time", "Flood continuously, which always uses less water", "Either method uses the same water on clay loam", "Neither, reclamation requires deep tillage only"], a: 0,
    why: "Continuous ponding on clay loam uses K = 0.3 while sprinkling uses K = 0.1 (Eq. 7.9 vs 7.10), so sprinkling needs one-third the water. The tradeoff is a longer reclamation period.",
    eq: "7.10", calc: "eq-7.9-7.10", fig: null, table: null },
  { id: "7-099", ch: 7, sec: "7.7", page: 140, type: "scenario", level: 3,
    q: "\"I run an orchard with somewhat saline well water. I like to let salinity build through summer and leach with winter rains.\" What caution do you give?",
    opts: ["That plan is ideal for all crops including trees", "Leach only in early spring after bloom", "Trees form next year's buds in the second half of the season, so keep salinity below threshold then or next year's crop suffers", "Trees never need leaching because they are deep rooted"], a: 2,
    why: "Letting salinity rise late in the season works for many annual crops, but the book names perennials as the exception because bud formation happens then.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-100", ch: 7, sec: "7.7", page: 140, type: "scenario", level: 2,
    q: "\"My center pivot leaves salty dry patches. I plan to bump the application rate to push the salt out.\" What is the better first step?",
    opts: ["Apply 50% more water on every pass", "Add gypsum to the whole field", "Switch to a more salt sensitive crop", "Check and improve application uniformity, since more water everywhere overwaters the rest of the field"], a: 3,
    why: "The book says salt and water stress from nonuniformity is best solved by a more uniform system rather than applying more water to compensate.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-101", ch: 7, sec: "7.8", page: 141, type: "scenario", level: 2,
    q: "\"I want to reclaim a saline field that sits over a shallow water table with no outlet.\" What is the key requirement before spending money on leaching water?",
    opts: ["Apply gypsum to the whole field", "Use only rainwater for leaching", "Provide drainage, natural or artificial, because without it reclamation is not feasible", "Plant a tolerant crop and skip leaching"], a: 2,
    why: "Adequate drainage is essential. Without storage below the root zone or a draining layer, leached salt returns with the rising water table.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-102", ch: 7, sec: "7.6", page: 138, type: "scenario", level: 2,
    q: "\"My almond leaves get burnt edges after sprinkling with our chloride-rich well water on hot afternoons.\" What do you suggest?",
    opts: ["Avoid wetting the foliage in hot, dry conditions, for example by irrigating at night or switching to drip or microsprinklers under the canopy", "Increase the sprinkling frequency during the afternoon", "Add more nitrogen to the fertigation", "Raise the pressure so the droplets are finer"], a: 0,
    why: "Chloride is absorbed through wetted leaves, and damage is most acute at high temperature and low humidity. Keeping water off leaves in those conditions reduces burn.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-103", ch: 7, sec: "7.7", page: 140, type: "scenario", level: 3,
    q: "\"My irrigation water is 1.0 dS/m and drainage samples below my corn root zone read 4.0 dS/m. No rain soaks in during the season. Am I leaching enough?\" What do you tell the grower?",
    opts: ["No, the leaching fraction is 0.25 but corn needs 0.40", "Yes, the actual leaching fraction is 0.25, above the corn requirement of about 0.11 from Figure 7.11", "No, the leaching fraction is 0.04, far too low", "Yes, the leaching fraction is 4.0, which is more than enough"], a: 1,
    why: "Lf = Ca/Cd = 1.0/4.0 = 0.25. For corn (T = 1.7) with ECa = 1.0, T/ECa = 1.7 sits between the 0.10 and 0.15 lines, so Lr is about 0.11. He is leaching more than needed and could cut water.",
    eq: "7.6a", calc: "leaching-fraction", fig: "7.11", table: null },
  { id: "7-104", ch: 7, sec: "7.4", page: 136, type: "scenario", level: 1,
    q: "\"Our soil ECe is about 7 dS/m and alfalfa yields are falling off. What can I grow there without much yield loss?\" Which crop do you suggest from Table 7.2?",
    opts: ["Corn (T = 1.7 dS/m)", "Clover (T = 1.5 dS/m)", "Potato (T = 1.7 dS/m)", "Barley (T = 8.0 dS/m)"], a: 3,
    why: "At ECe 7 dS/m, barley is still below its threshold of 8.0. Corn, clover, and potato would lose most of their yield.",
    eq: null, calc: null, fig: null, table: "7.2" },
  { id: "7-105", ch: 7, sec: "7.7", page: 140, type: "scenario", level: 2,
    q: "\"Our well water is low in salt and we get good winter rains. Do I have to leach every irrigation?\" What do you tell the grower?",
    opts: ["Yes, every irrigation must include a 0.30 leaching fraction", "Yes, otherwise sodium will build up within one season", "No, low salt water never needs leaching under any conditions", "No, leaching is only needed when root zone salinity approaches the crop threshold, and winter rain may do it"], a: 3,
    why: "The book says leaching is not required until salinity passes the threshold. If soil and water are low in salt, no leaching may be needed for several years, especially with significant rain.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-106", ch: 7, sec: "7.7", page: 139, type: "scenario", level: 3,
    q: "\"We put on 30 inches of 1.5 dS/m water. The crop can stand drainage water up to 7.5 dS/m.\" How much water must pass below the root zone?",
    opts: ["6.0 in", "3.0 in", "1.2 in", "150 in"], a: 0,
    why: "Lr = ECa/ECd* = 1.5/7.5 = 0.20 (Eq. 7.8). dp* = 0.20 × 30 = 6.0 in. 150 inverts the ratio.",
    eq: "7.8", calc: "eq-7.8", fig: null, table: null },
  { id: "7-107", ch: 7, sec: "7.2", page: 134, type: "scenario", level: 2,
    q: "\"How much salt am I actually putting on with my 700 mg/L well water at 20 inches per year on 80 acres?\" What is the answer?",
    opts: ["About 3,164 tons per year", "About 127 tons per year", "About 32 tons per year", "About 1.6 tons per year"], a: 1,
    why: "Salt = 0.226 × 700 × 20 = 3,164 lb/ac. Times 80 ac divided by 2,000 = 127 tons. 3,164 is the pounds per acre, and 1.6 tons is the per-acre figure in tons.",
    eq: null, calc: "salt-applied", fig: null, table: null },
  { id: "7-108", ch: 7, sec: "7.8", page: 143, type: "scenario", level: 3,
    q: "\"My sodic field has a gypsum layer about 2 feet down. Do I need to buy an amendment?\" What do you tell the grower?",
    opts: ["Yes, buried gypsum never helps", "No amendment is ever needed for sodic soils", "Deep tillage to mix that subsoil calcium into the shallow sodic layer may reduce or eliminate the need", "Apply sulfur because gypsum adds sodium"], a: 2,
    why: "The book says calcium present in the subsoil can be mixed into a shallow sodic layer by deep tillage. Typically the soil is also tilled before each intermittent water application during reclamation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "7-109", ch: 7, sec: "7.1", page: 132, type: "table", level: 1,
    q: "Per Table 7.1, about what share of irrigated land in the United States was damaged by salination in the mid-1980s?",
    opts: ["24%", "36%", "13%", "27%"], a: 3,
    why: "Table 7.1 lists the United States at 13 million acres damaged, 27% of its irrigated land. 24% is the world figure, 36% is India, and 13 is the US acreage in millions.",
    eq: null, calc: null, fig: null, table: "7.1" },
  { id: "7-110", ch: 7, sec: "7.1", page: 132, type: "table", level: 2,
    q: "Per Table 7.1, which country had the largest irrigated area damaged by salination in the mid-1980s?",
    opts: ["India, about 50 million acres", "China, about 18 million acres", "United States, about 13 million acres", "Pakistan, about 8 million acres"], a: 0,
    why: "India had 50 million acres damaged (36% of its irrigated land), a third of the world total of 150 million acres.",
    eq: null, calc: null, fig: null, table: "7.1" }
]);
